from pathlib import Path
import json
ROOT=Path(__file__).resolve().parents[1]
def b(id,type,text='',**kw): return dict(id=id,type=type,text=text,**kw)
def p(id,text): return b(id,'paragraph',text)
def prompt(id,text): return b(id,'prompt',text)
def crop(name,page,box,**kw):return b(name,'figure',source_page=page,bbox_normalized=box,**kw)
questions=[]
def add(n,points,page,blocks,items,box,notes=[]):
 questions.append(dict(number=n,points=points,source_pages=[page],blocks=blocks,items=items,question_bbox=[{'page':page,'bbox_normalized':box}],notes=notes))
add(16,8,5,[
 p('16.m1','纵观整个人类发展史，凡是社会大发展、大变革的时代，也是人文学科推陈出新的时代，比如我国春秋战国时期的百家争鸣、西方的文艺复兴等。当前，面对技术进步带来的社会巨变，人们迫切需要为这个充满机遇与挑战的时代注入新的思想活力。'),
 p('16.m2','人工智能可以完成写作、翻译、分析信息等工作，人文学科能教人如何辨析价值冲突。技术再进步，“人何以为人”的思考永不过时。技术可以模拟语言，却未必理解语言背后的情感；算法可以识别图像，却无法体验图像所承载的历史记忆。当我们拥有足够的历史意识、伦理意识和文化理解时，技术才能真正成为文明进步的工具，而不是新的风险来源。人工智能为我们赋能，人文学科为人工智能赋魂。'),
 prompt('16.ask','有人说，人文学科在人工智能时代具有不可替代的价值。结合材料，运用《哲学与文化》知识，谈谈对这一观点的认识。')
],[{'id':'Q16','points':8,'depends_on':['16.m1','16.m2','16.ask'],'modules':['必修四哲学','必修四文化'],'tags':['发展','社会存在与社会意识','价值观','文化的功能'],'rubric_ids':['R16']}],[.12,.135,.89,.375])
add(17,6,5,[
 p('17.m','调查研究要讲求科学方法。某校“模拟政协”社团同学准备围绕本市无障碍环境建设情况展开调研。以下是同学们设计的调查问卷（节选）。'),
 b('17.survey','boxed_text','调查问卷（节选）',paragraphs=['问题1. 您的身份（单选）：','□老年人（60岁及以上）　□残障人士　□儿童（14岁以下）','□普通在职职工　□离退休人员','□相关行业从业者（如城市管理、物业等）','□其他________','问题2. 您认为本市无障碍设施存在的主要问题是（可多选）：','□设计不合理　□标识不清　□相关部门维护不到位'],source_page=5,bbox_normalized=[.163,.527,.851,.752],layout={'option_rows':[3,2,1,1,3],'border':'dotted','preserve_checkbox':True}),
 prompt('17.ask_a','运用《逻辑与思维》知识，指出上述调查问卷中的逻辑错误。（2分）'),
 prompt('17.ask_b','为提高调研活动的科学性，提出具体可行的建议。（4分）')
],[{'id':'Q17-a','points':2,'depends_on':['17.m','17.survey','17.ask_a'],'modules':['选必三推理'],'tags':['划分','选言判断'],'rubric_ids':['R17'],'original_subquestion_number':None,'task_note':'原卷连续设问，a为后台任务键，不在原题中添加（1）。'},
 {'id':'Q17-b','points':4,'depends_on':['17.m','17.survey','17.ask_a','17.ask_b'],'modules':['选必三思维','选必三推理'],'tags':['科学思维','辩证思维','创新思维','逻辑思维规则'],'rubric_ids':['R17'],'original_subquestion_number':None,'task_note':'保留前一设问提供的知识限定；b为后台任务键，不在原题中添加（2）。'}],[.12,.455,.90,.802])
add(18,15,6,[
 p('18.intro','消费是经济增长的持久动力，事关民生福祉。'),
 p('18.m1','材料一　随着我国居民生活水平提高，服务消费日益成为经济高质量发展的重要引擎。'),
 crop('18.chart',6,[.178,.115,.780,.332],caption='2021—2025年全国居民人均服务性消费支出及占比',alt='双轴柱线图；左轴为人均服务性消费支出（元），右轴为占居民人均消费支出比重（%）；年份2021至2025。',layout={'width_fraction_of_content':.79,'note_separate':True},data_policy='原图未标出各年精确数值；不由柱高或线点反推精确数据。扫描图部分线迹较浅，原图保留，可辨总体趋势。'),
 b('18.note','note','注：服务性消费支出，是指住户用于各种生活服务的消费支出，包括餐饮服务、教育文化娱乐服务、医疗服务、居住服务、家庭服务、交通通信服务和其他服务。',layout={'relative_font_scale':.78,'width_fraction_of_content':.93,'keep_with':'18.chart'}),
 prompt('18.ask1','（1）材料一反映了什么信息？（2分）'),
 prompt('18.ask2','（2）服务消费，一头连着经济，一头连着民生。结合材料一，运用《经济与社会》知识，说明服务消费在推动经济高质量发展方面的作用。（6分）'),
 p('18.m2','材料二　聚焦新领域，人民法院以高质量司法维护消费者合法权益，营造放心消费环境。下列是人民法院受理的两个案件：'),
 p('18.case1','【案件1】张某等人因不满商家的“剧本杀”游戏服务，上网发布差评，随后商家在社交平台发布张某等人的游戏包厢监控视频录像片段、网络聊天信息等。张某等人起诉要求商家停止侵权、赔礼道歉及赔偿精神损失等。'),
 p('18.case2','【案件2】赵某在网络平台宣传某理疗产品具有“治疗糖尿病并发症”等功效，孙某看到后至赵某经营的理疗店体验，并购买了10个疗程的理疗项目，4个疗程后并无效果。孙某与赵某协商退换未果，遂向法院提起诉讼，要求其返还已支付的费用并承担三倍价款的惩罚性赔偿责任。法院支持了原告诉讼请求。'),
 prompt('18.ask3','（3）阅读材料二，运用《法律与生活》知识，完成下表。（7分）'),
 b('18.table','table',headers=['案件','裁判结果','裁判理由'],rows=[['案件1','①','②'],['案件2','支持原告诉讼请求','③']],merged_cells=[],source_page=6,bbox_normalized=[.154,.690,.879,.830],layout={'column_widths':[.18,.30,.52]})
],[{'id':'Q18-1','points':2,'depends_on':['18.intro','18.m1','18.chart','18.note','18.ask1'],'modules':['必修二'],'tags':['消费结构','图表信息'],'rubric_ids':['R18-1']},
 {'id':'Q18-2','points':6,'depends_on':['18.intro','18.m1','18.chart','18.note','18.ask2'],'modules':['必修二'],'tags':['服务消费','高质量发展','内需','产业结构','民生'],'rubric_ids':['R18-2']},
 {'id':'Q18-3','points':7,'depends_on':['18.intro','18.m2','18.case1','18.case2','18.ask3','18.table'],'modules':['选必二'],'tags':['隐私权','消费者权益','知情权','侵权责任'],'rubric_ids':['R18-3']}],[.12,.06,.89,.835])
add(19,8,7,[
 p('19.m1','材料一　全国统一大市场建设正纵深推进。国务院发布的《公平竞争审查条例》规定，行政机关起草涉及经营者经济活动的法律、行政法规、地方性法规、规章、规范性文件以及具体政策措施应当依照条例规定开展公平竞争审查。该条例规定，起草政策措施，不得含有限制或者变相限制市场准入和退出、限制商品和要素自由流动、不当影响生产经营成本和影响生产经营行为的内容。'),
 p('19.m2','材料一　为规范网络预约出租汽车经营服务行为，保障运营安全和乘客合法权益，交通运输部等七部门联合发布《网络预约出租汽车经营服务管理暂行办法》。'),
 b('19.reg','boxed_text','《网络预约出租汽车经营服务管理暂行办法》',paragraphs=['第十二条　拟从事网约车经营的车辆，应当符合以下条件：','（一）7座及以下乘用车；','（二）安装具有行驶记录功能的车辆卫星定位装置、应急报警装置；','（三）车辆技术性能符合运营安全相关标准要求。','车辆的具体标准和营运要求，由相应的出租汽车行政主管部门，按照高品质服务、差异化经营的发展原则，结合本地实际情况确定。'],source_page=7,bbox_normalized=[.175,.218,.869,.385],layout={'border':'dotted'}),
 p('19.m3','某地政府部门依据《网络预约出租汽车经营服务管理暂行办法》制定了相应的《实施细则》。《实施细则》规定，拟从事网约车经营的车辆，应当符合车辆初次注册登记时的实际购置总价不低于12万元的条件。有公民对这一规定提出审查建议。全国人大法工委经审查认定《实施细则》的这一规定属于应予纠正的情形。'),
 prompt('19.ask','结合材料，运用《政治与法治》知识，说明全国人大法工委作出这一审查结论的理由。')
],[{'id':'Q19','points':8,'depends_on':['19.m1','19.m2','19.reg','19.m3','19.ask'],'modules':['必修三','必修二'],'primary_modules':['必修三'],'cross_module_note':'设问限定政治与法治；正式细则意义项明确允许市场角度（统一大市场、公平竞争、资源配置）。经济仅为评分角度索引，不改写设问或把整题当纯经济题。','tags':['备案审查','法律层级','法治政府','统一大市场','公平竞争'],'rubric_ids':['R19']}],[.12,.064,.894,.498],['原卷两段材料标签均为“材料一”，按可见原卷保留，不静默改成材料二。'])
add(20,8,7,[
 p('20.m1','国际标准是全球产业界的“通用语言”。从手机充电接口的统一，到食品包装上的营养成分标注；从电梯运行的安全规范，到空气质量的监测指标，背后都离不开“标准”的支撑。它让不同国家、不同企业的产品能互通兼容，让全球资源能更高效利用。'),
 p('20.m2','近年来，从低碳能源到人工智能，从北斗导航到传统医学，越来越多的中国标准走出国门，融入全球产业发展体系，中国与世界深度互动、共享发展。2025年，我国在国际标准的制定与推广中交出了亮眼成绩单。'),
 b('20.cards','parallel_boxes','',paragraphs=['2025年我国在低碳能源、生物技术、人工智能、工业网络等前沿领域，共向ISO、IEC提交提案505项，较2024年增长15.83%。','2025年我国在新能源、智慧电网、传统医学、脑机接口等领域，牵头制定发布285项ISO、IEC国际标准，同比增长26.67%。'],source_page=7,bbox_normalized=[.162,.686,.856,.785],layout={'columns':2,'column_gap_fraction':.08,'equal_width':True}),
 b('20.note','note','注：ISO（国际标准化组织）和IEC（国际电工委员会）是全球最具权威性的两大国际标准化机构。',layout={'relative_font_scale':.78}),
 prompt('20.ask','结合材料，运用《当代国际政治与经济》知识，谈谈中国标准走出国门的意义。')
],[{'id':'Q20','points':8,'depends_on':['20.m1','20.m2','20.cards','20.note','20.ask'],'modules':['选必一','必修二'],'primary_modules':['选必一'],'cross_module_note':'保留设问限定；正式细则的制度型开放、国内国际两个市场两种资源与新发展格局可供必修二跨模块索引。','tags':['制度型开放','新发展格局','经济全球化','全球治理'],'rubric_ids':['R20']}],[.12,.53,.89,.835])
add(21,10,8,[
 p('21.m1','锐始者必图其终，成功者先计于始。这是先贤治国理政、经世济民的智慧，也契合了中国共产党人一以贯之的战略思维和实干精神。'),
 p('21.m2','“一五”到“十五五”，见证了新中国从工业化奠基到高质量发展的历史进程。回顾历史，中国共产党人始终把科学谋划与真抓实干有机结合。从“一辆汽车、一架飞机、一辆坦克、一辆拖拉机都不能造”到“铁路进青藏，公路密成网，高峡出平湖，港口连五洋，产业门类齐，稻麦遍地香，神舟遨太空，国防更坚强”的伟大飞跃……规划与执行相互促进，宏伟蓝图变为现实图景。'),
 b('21.aside','boxed_text','',paragraphs=['“锐始者必图其终，成功者先计于始”，出自明代张居正《答中丞孙槐溪》。这句话告诫人们做事要善始善终、谋定后动，唯有在开始时便胸怀全局、谋划长远，并以坚韧不拔的毅力向着既定目标笃行，方能成就事业。'],source_page=8,bbox_normalized=[.526,.088,.893,.233],layout={'position':'float-right','width_fraction_of_content':.48,'anchor':'21.m1','wrap_through':'21.m2','border':'dotted'}),
 prompt('21.ask','“中国有一大优势，总是制定各种规划，而且各种规划总是能实现。”结合材料，综合运用所学，阐述你对这一观点的理解。')
],[{'id':'Q21','points':10,'depends_on':['21.m1','21.m2','21.aside','21.ask'],'modules':['必修三','必修四哲学','必修四文化','选必三思维'],'tags':['党的领导','人民代表大会制度','人民立场','科学思维','文化支撑','规划制定与执行'],'rubric_ids':['R21'],'cross_module_note':'知识范围为综合运用所学；选三维度评分，不将四类示例全部当必答，也不把其中单册角度当整题全部得分。'}],[.12,.064,.90,.35])
